import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int b = (int) nextLong(), length = (int) nextLong();
        long[] v = new long[b];
        // pack (start, finish) into one long so a primitive sort orders by start then finish
        for (int i = 0; i < b; i++) v[i] = nextLong() * 2048 + nextLong();
        Arrays.sort(v);
        long end = 0;  // right edge of the busy time scanned so far
        for (long x : v) {
            long start = x / 2048, finish = x % 2048;
            if (start - end >= length) {
                System.out.println(end);
                return;
            }
            end = Math.max(end, finish);
        }
        System.out.println(1440 - end >= length ? end : -1);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Split(bufio.ScanWords)
	next := func() int {
		sc.Scan()
		v, _ := strconv.Atoi(sc.Text())
		return v
	}
	b, length := next(), next()
	v := make([][2]int, b)
	for i := range v {
		v[i][0], v[i][1] = next(), next()
	}
	sort.Slice(v, func(x, y int) bool {
		if v[x][0] != v[y][0] {
			return v[x][0] < v[y][0]
		}
		return v[x][1] < v[y][1]
	})
	end := 0 // right edge of the busy time scanned so far
	for _, p := range v {
		if p[0]-end >= length {
			fmt.Println(end)
			return
		}
		end = max(end, p[1])
	}
	if 1440-end >= length {
		fmt.Println(end)
	} else {
		fmt.Println(-1)
	}
}
